settings.html:
[stillness_featured_event]
<style>
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;0,500;1,300;1,400&family=Jost:wght@300;400;500&display=swap');

.stillness-featured-event {
  display: grid !important;
  grid-template-columns: 1fr 1fr !important;
  align-items: stretch !important;
  background: #F7F0EC !important;
}
.stillness-featured-event:empty { display: none !important; }

.stillness-feat-img-wrap,
.stillness-feat-waitlist-panel {
  width: 100% !important;
  min-height: 640px !important;
  overflow: hidden !important;
  position: relative !important;
}
.stillness-feat-img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  object-position: center !important;
  transition: transform 16s ease !important;
  display: block !important;
}
.stillness-featured-event:hover .stillness-feat-img { transform: scale(1.05) !important; }

.stillness-feat-waitlist-panel {
  background: linear-gradient(135deg, #0E1B30 0%, #1D3152 55%, #688F9D 100%) !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}
.stillness-feat-waitlist-panel::before {
  content: '' !important;
  position: absolute !important;
  inset: 12% !important;
  border: 0.5px solid rgba(217,232,235,0.28) !important;
}
.stillness-feat-waitlist-panel span {
  position: relative !important;
  z-index: 1 !important;
  font-family: 'Cormorant Garamond', serif !important;
  font-size: clamp(3rem, 6vw, 6rem) !important;
  font-weight: 300 !important;
  font-style: italic !important;
  color: #F7F0EC !important;
  opacity: 0.9 !important;
}

.stillness-featured-event.is-sold-out .stillness-feat-img-wrap::after {
  content: '' !important;
  position: absolute !important;
  inset: 0 !important;
  background: rgba(14, 27, 48, 0.45) !important;
}
.stillness-feat-sold-badge {
  position: absolute !important;
  top: 24px !important;
  left: 24px !important;
  z-index: 2 !important;
  font-family: 'Jost', sans-serif !important;
  font-size: 9px !important;
  font-weight: 500 !important;
  letter-spacing: 0.25em !important;
  text-transform: uppercase !important;
  color: #F7F0EC !important;
  background: rgba(14, 27, 48, 0.72) !important;
  padding: 8px 16px !important;
}

.stillness-feat-text {
  padding: 6rem !important;
  display: flex !important;
  flex-direction: column !important;
  justify-content: center !important;
}
.stillness-feat-label {
  display: block !important;
  font-family: 'Jost', sans-serif !important;
  font-size: 0.63rem !important;
  letter-spacing: 0.42em !important;
  text-transform: uppercase !important;
  color: #688F9D !important;
  margin-bottom: 1.25rem !important;
}
.stillness-feat-title {
  font-family: 'Cormorant Garamond', serif !important;
  font-size: clamp(2.2rem, 4vw, 3.8rem) !important;
  font-weight: 300 !important;
  color: #0E1B30 !important;
  line-height: 1.08 !important;
  margin: 0 0 1.6rem !important;
}
.stillness-feat-attrs {
  display: grid !important;
  grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
  gap: 1rem !important;
  padding: 1rem 0 !important;
  margin: 0 0 2rem !important;
  border-top: 0.5px solid rgba(104,143,157,0.22) !important;
  border-bottom: 0.5px solid rgba(104,143,157,0.22) !important;
}
.stillness-feat-attr span {
  display: block !important;
  font-family: 'Jost', sans-serif !important;
  font-size: 0.58rem !important;
  letter-spacing: 0.24em !important;
  text-transform: uppercase !important;
  color: #688F9D !important;
  margin-bottom: 0.35rem !important;
}
.stillness-feat-attr strong {
  display: block !important;
  font-family: 'Jost', sans-serif !important;
  font-size: 0.78rem !important;
  font-weight: 300 !important;
  line-height: 1.55 !important;
  color: rgba(14,27,48,0.68) !important;
}
.stillness-feat-desc {
  margin-bottom: 2.5rem !important;
}
.stillness-feat-desc p {
  font-family: 'Jost', sans-serif !important;
  font-size: 0.9rem !important;
  line-height: 1.9 !important;
  color: rgba(14,27,48,0.7) !important;
  margin: 0 0 1rem !important;
}
.stillness-feat-desc p:last-child { margin-bottom: 0 !important; }
.stillness-feat-desc blockquote {
  font-family: 'Cormorant Garamond', serif !important;
  font-size: clamp(1.1rem, 1.8vw, 1.5rem) !important;
  font-weight: 300 !important;
  font-style: italic !important;
  color: #0E1B30 !important;
  line-height: 1.6 !important;
  margin: 0 0 2rem !important;
  border-left: 1px solid #688F9D !important;
  padding-left: 1.5rem !important;
}
.stillness-feat-btn {
  display: inline-block !important;
  align-self: flex-start !important;
  font-family: 'Jost', sans-serif !important;
  font-size: 0.7rem !important;
  font-weight: 500 !important;
  letter-spacing: 0.2em !important;
  text-transform: uppercase !important;
  color: #F7F0EC !important;
  background: #0E1B30 !important;
  padding: 1rem 2.2rem !important;
  text-decoration: none !important;
  transition: background 0.3s ease, transform 0.2s ease !important;
  border: none !important;
  outline: none !important;
  line-height: 1 !important;
}
.stillness-feat-btn:hover { background: #1D3152 !important; transform: translateY(-2px) !important; }
.stillness-feat-btn--waitlist { background: #688F9D !important; }
.stillness-feat-btn--waitlist:hover { background: #A4B2BA !important; }

@media (max-width: 900px) {
  .stillness-featured-event { grid-template-columns: 1fr !important; }
  .stillness-feat-img-wrap,
  .stillness-feat-waitlist-panel { min-height: 420px !important; }
  .stillness-feat-text { padding: 4rem 2rem !important; }
}
@media (max-width: 768px) {
  .stillness-feat-img-wrap,
  .stillness-feat-waitlist-panel { min-height: 320px !important; }
  .stillness-feat-text { padding: 3rem 1.5rem !important; }
  .stillness-feat-attrs { grid-template-columns: 1fr !important; gap: 0.8rem !important; }
}
</style>
